oxy_webhelp_navlinks = {"postgresql_recovery-d39536e40434":{"topics":[{"title":"PostgreSQL recovery options","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides flexible options for PostgreSQL cluster recovery from         secure, immutable backups.<\/p>","href":"postgresql\/postgresql_recovery_options.html","attributes":{"data-id":"postgresql_recovery_options"},"menu":{"hasChildren":false},"tocID":"postgresql_recovery_options-d39536e40448","topics":[]},{"title":"PostgreSQL log snapshot visibility","shortdesc":"<p class=\"shortdesc\">When you perform point-in-time recovery of a PostgreSQL cluster, you can view log         snapshots that cover a recovery point on the snapshot calendar and in the recovery         details.<\/p>","href":"postgresql\/postgresql_log_snapshot_visibility.html","attributes":{"data-id":"postgresql_log_snapshot_visibility"},"menu":{"hasChildren":false},"tocID":"postgresql_log_snapshot_visibility-d39536e40461","next":"postgresql_log_snapshot_visibility-d39536e40461"},{"title":"Creating a restore mount point for a PostgreSQL cluster","shortdesc":"<p class=\"shortdesc\">To recover a PostgreSQL cluster, create a restore mount point by mounting a snapshot         of backup data to the mount point using NFS and then performing the recovery         instructions.<\/p>","href":"postgresql\/creating_restore_mp_postgresql.html","attributes":{"data-id":"creating_restore_mp_postgresql"},"menu":{"hasChildren":false},"tocID":"creating_restore_mp_postgresql-d39536e40486","topics":[]},{"title":"Unmounting restore mount point after PostgreSQL cluster recovery","shortdesc":"<p class=\"shortdesc\">After recovering a PostgreSQL cluster, unmount it to remove the metadata associated         with the selected PostgreSQL cluster.<\/p>","href":"postgresql\/unmounting_restore_mount_point_postgresql_cluster.html","attributes":{"data-id":"unmounting_restore_mount_point_postgresql_cluster"},"menu":{"hasChildren":false},"tocID":"unmounting_restore_mount_point_postgresql_cluster-d39536e40497","topics":[]},{"title":"Recovering a PostgreSQL cluster","shortdesc":"<p class=\"shortdesc\">After you have created a mount point for the PostgreSQL cluster, recover the cluster         manually by following the recovery instructions.<\/p>","href":"postgresql\/recovering_postgresql_cluster.html","attributes":{"data-id":"recovering_postgresql_cluster"},"menu":{"hasChildren":false},"tocID":"recovering_postgresql_cluster-d39536e40508","topics":[]},{"title":"PostgreSQL automated recovery","shortdesc":"<p class=\"shortdesc\">PostgreSQL automated recovery enables you to recover PostgreSQL clusters on <span class=\"ph\">RSC<\/span> from Rubrik CDM versions 9.4.1 and later without requiring manual         steps.<\/p>","href":"postgresql\/postgresql_automated_recovery.html","attributes":{"data-id":"postgresql_automated_recovery"},"menu":{"hasChildren":false},"tocID":"postgresql_automated_recovery-d39536e40519","next":"postgresql_automated_recovery-d39536e40519"}]}};